from manim import *

class DerivativeTangentZoom(Scene):
    def construct(self):
        def f(x):
            return 0.22 * (x - 0.8) ** 2 + 0.35
        def p(x):
            return axes.c2p(x, f(x))
        def tangent_segment(x):
            slope = 0.44 * (x - 0.8)
            left, right = x - 0.55, x + 0.55
            return Line(axes.c2p(left, f(x) + slope * (left - x)), axes.c2p(right, f(x) + slope * (right - x)), color=YELLOW_D, stroke_width=5)
        def slope_label(x):
            return VGroup(MathTex("m=", font_size=30), DecimalNumber(0.44 * (x - 0.8), num_decimal_places=2, font_size=28, color=YELLOW_D)).arrange(RIGHT, buff=0.08).to_corner(UR).shift(DOWN * 0.75)

        title = Text("Derivative = local slope", font_size=34).to_edge(UP)
        axes = Axes(x_range=[-3, 3, 1], y_range=[0, 2.4, 0.5], x_length=7.2, y_length=4.2, tips=False).shift(DOWN * 0.15)
        curve = axes.plot(f, x_range=[-2.6, 2.8], color=BLUE_D)
        tracker = ValueTracker(-1.4)
        dot = always_redraw(lambda: Dot(p(tracker.get_value()), color=YELLOW_D, radius=0.08))
        tangent_start = tangent_segment(-1.4)
        tangent_end = tangent_segment(1.9)
        label_start = slope_label(-1.4)
        label_end = slope_label(1.9)
        caption = Text("A derivative reads the curve at one small neighborhood.", font_size=24, color=WHITE).to_edge(DOWN)
        caption_box = SurroundingRectangle(caption, color=YELLOW_D, buff=0.18)

        self.play(FadeIn(title), Create(axes), Create(curve), run_time=3)
        self.play(FadeIn(dot), Create(tangent_start), FadeIn(label_start), run_time=2)
        self.play(tracker.animate.set_value(1.9), Transform(tangent_start, tangent_end), ReplacementTransform(label_start, label_end), run_time=5)
        self.play(FadeIn(caption), Create(caption_box), run_time=2)
        self.wait(3)
